const express = require('express');
const app = express();
const logs = [];

app.use((req, res, next) => {
  res.status(404).send("Sorry, that route doesn't exist. Have a nice day!");
});
app.get('/Hello', (req, res) => res.send('Hello, World!'));

module.exports = { app, logs };

